def aggregate_metrics(api_responses):
    metrics = {'total': 0, 'errors': 0, 'success': 0}
    for response in api_responses:
        metrics['total'] += 1
        if response.get('status') == 'error':
            metrics['errors'] += 1
        else:
            metrics['success'] += 1

    success_rate = metrics['success'] / metrics['total'] if metrics['total'] > 0 else 0
    return success_rate

responses = [
