def comprehensive_project(api_urls):
    all_data = []
    stats = {'total': 0, 'valid': 0, 'invalid': 0}

    for url in api_urls:
        try:
            response = requests.get(url, timeout=2)
            data = response.json() if response.status_code == 200 else []

            for item in data:
                stats['total'] += 1
                if item.get('id') and item.get('value'):
                    all_data.append(item)
                    stats['valid'] += 1
                else:
                    stats['invalid'] += 1
        except Exception:
            pass

    return {
        'items': len(all_data),
        'valid_ratio': stats['valid'] / stats['total'] if stats['total'] > 0 else 0
    }

# API 1에서 [{id:1, value:10}, {id:2}] 반환
# API 2에서 [{id:3, value:30}] 반환
result = comprehensive_project(['api1', 'api2'])
print(f'{result["items"]}개 유효, 성공률 {result["valid_ratio"]:.0%}')
```

