def validate_project_output(output_file):
    try:
        with open(output_file, 'r') as f:
            data = json.load(f)

        # 구조 검증
        if not isinstance(data, list):
            return {'valid': False, 'error': 'Not a list'}

        # 내용 검증
        required = ['id', 'name']
        for item in data:
            if not all(field in item _____ item[field] for field in required):
                return {'valid': False, 'error': 'Missing required fields'}

        return {'valid': True, 'count': len(data)}
    except Exception as e:
        return {'valid': False, 'error': str(e)}
```

