```python
import json, requests, time
from datetime import datetime

def final_project():
    config = {
        'api_url': 'https://api.example.com/data',
        'output_file': 'final_output.json',
        'cache': {}
    }

    try:
        # Step 1: API 호출 (캐싱 적용)
        if 'data' not in config['cache']:
            response = requests.get(config['api_url'], timeout=5)
            response.raise_for_status()
            config['cache']['data'] = response.json()

        data = config['cache']['data']

        # Step 2: 데이터 검증 및 변환
        processed = []
        for item in data:
            if item.get('id') and item.get('status') == 'active':
                processed.append({
                    'id': item['id'],
                    'name': item.get('name', 'Unknown'),
                    'timestamp': datetime.now().isoformat()
                })

        # Step 3: 저장
        with open(config['output_file'], 'w') as f:
            json.dump(processed, f)

        return {
            'status': 'complete',
            'processed_count': len(processed),
            'output_file': config['output_file']
        }
    except Exception as e:
        return {
            'status': 'failed',
            'error': str(e)
        }

result = final_project()
print(f"프로젝트 {result['status']}")
```
